package com.primehr.succession.api;
import com.primehr.integration.administrative.PermissionDataScope; import com.primehr.security.*; import com.primehr.succession.application.SuccessionPlanningService; import com.primehr.succession.api.SuccessionFoundationDtos.*; import com.primehr.succession.api.SuccessionPlanningDtos.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/succession")
public class SuccessionPlanningController {
 private final SuccessionPlanningService service; private final SuccessionPlanningPermissionGuard permission; private final AgencyScopeResolver agency;
 public SuccessionPlanningController(SuccessionPlanningService service,SuccessionPlanningPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
 @GetMapping("/career-families") public List<CareerFamilyResponse> families(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.ACCESS,t);return service.careerFamilies(agency.resolveAgencyId(a));}
 @GetMapping("/career-families/{id}") public CareerFamilyResponse family(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.ACCESS,t);return service.getCareerFamily(agency.resolveAgencyId(a),id);}
 @PostMapping("/career-families") @ResponseStatus(HttpStatus.CREATED) public CareerFamilyResponse createFamily(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody CareerFamilyInput i){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.ADD,t);return service.createCareerFamily(agency.resolveAgencyId(a),i,c);}
 @PutMapping("/career-families/{id}") public CareerFamilyResponse updateFamily(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody CareerFamilyInput i){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.EDIT,t);return service.updateCareerFamily(agency.resolveAgencyId(a),id,i,c);}
 @PutMapping("/career-families/{id}/pathways") public CareerFamilyResponse pathways(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody PathLinksInput i){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.EDIT,t);return service.replacePathLinks(agency.resolveAgencyId(a),id,i,t,c);}
 @PostMapping("/career-families/{id}/revisions") @ResponseStatus(HttpStatus.CREATED) public CareerFamilyResponse reviseFamily(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.ADD,t);return service.reviseCareerFamily(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/career-families/{id}/publish") public CareerFamilyResponse publishFamily(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Publish i){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.PUBLISH,t);return service.publishCareerFamily(agency.resolveAgencyId(a),id,i,t,c);}
 @PostMapping("/career-families/{id}/retire") public CareerFamilyResponse retireFamily(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){req(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.ARCHIVE,t);return service.retireCareerFamily(agency.resolveAgencyId(a),id,i,c);}
 @GetMapping("/criticality-frameworks") public List<FrameworkResponse> frameworks(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){req(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ACCESS,t);return service.frameworks(agency.resolveAgencyId(a));}
 @GetMapping("/criticality-frameworks/{id}") public FrameworkResponse framework(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){req(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ACCESS,t);return service.getFramework(agency.resolveAgencyId(a),id);}
 @PostMapping("/criticality-frameworks") @ResponseStatus(HttpStatus.CREATED) public FrameworkResponse createFramework(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody FrameworkInput i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ADD,t);return service.createFramework(agency.resolveAgencyId(a),i,c);}
 @PutMapping("/criticality-frameworks/{id}") public FrameworkResponse updateFramework(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody FrameworkInput i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.EDIT,t);return service.updateFramework(agency.resolveAgencyId(a),id,i,c);}
 @PutMapping("/criticality-frameworks/{id}/criteria") public FrameworkResponse criteria(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody CriteriaInput i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.EDIT,t);return service.replaceCriteria(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/criticality-frameworks/{id}/revisions") @ResponseStatus(HttpStatus.CREATED) public FrameworkResponse reviseFramework(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ADD,t);return service.reviseFramework(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/criticality-frameworks/{id}/publish") public FrameworkResponse publishFramework(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Publish i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.PUBLISH,t);return service.publishFramework(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/criticality-frameworks/{id}/retire") public FrameworkResponse retireFramework(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ARCHIVE,t);return service.retireFramework(agency.resolveAgencyId(a),id,i,c);}
 @GetMapping("/critical-positions") public List<DesignationResponse> designations(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){var s=req(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ACCESS,t);return service.designations(agency.resolveAgencyId(a),a.getName(),s==PermissionDataScope.ASSIGNED_RECORDS);}
 @GetMapping("/critical-positions/{id}") public DesignationResponse designation(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=req(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ACCESS,t);return service.getDesignation(agency.resolveAgencyId(a),id,a.getName(),s==PermissionDataScope.ASSIGNED_RECORDS);}
 @PostMapping("/critical-positions") @ResponseStatus(HttpStatus.CREATED) public DesignationResponse createDesignation(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody DesignationInput i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ADD,t);return service.createDesignation(agency.resolveAgencyId(a),i,t,c);}
 @PutMapping("/critical-positions/{id}") public DesignationResponse updateDesignation(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody DesignationInput i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.EDIT,t);return service.updateDesignation(agency.resolveAgencyId(a),id,i,t,c);}
 @PostMapping("/critical-positions/{id}/submit") public DesignationResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.SUBMIT,t);return service.submitDesignation(agency.resolveAgencyId(a),id,i,t,c);}
 @PostMapping("/critical-positions/{id}/approve") public DesignationResponse approve(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody DesignationDecision i){req(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.APPROVE,t);return service.approveDesignation(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/critical-positions/{id}/reject") public DesignationResponse reject(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody DesignationDecision i){req(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.APPROVE,t);return service.rejectDesignation(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/critical-positions/{id}/retire") public DesignationResponse retire(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody DesignationDecision i){reqAgency(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.FINALIZE,t);return service.retireDesignation(agency.resolveAgencyId(a),id,i,c);}
 private PermissionDataScope req(String f,PrimeHrAction a,String t){return permission.require(f,a,t);} private void reqAgency(String f,PrimeHrAction a,String t){if(req(f,a,t)!=PermissionDataScope.AGENCY_WIDE)throw new org.springframework.security.access.AccessDeniedException("This action requires Agency Wide scope");}
}
